import Foundation
import SceneGLTestSupport
import XCTest

final class VideoTextureDecoderTests: XCTestCase {
    func testLogicalAssetPathDoesNotBecomeTemporaryFilesystemPath() throws {
        let encoded = ""
        let data = try XCTUnwrap(Data(base64Encoded: encoded))
        var width: UInt32 = 0
        var height: UInt32 = 0
        let result = data.withUnsafeBytes { bytes in
            "materials/videos/demo.mp4".withCString { source in
                we_scene_gl_test_decode_video(
                    bytes.baseAddress?.assumingMemoryBound(to: UInt8.self),
                    bytes.count,
                    source,
                    &width,
                    &height
                )
            }
        }

        XCTAssertEqual(result, 1)
        XCTAssertEqual(width, 16)
        XCTAssertEqual(height, 16)
    }
}
